// Testes do módulo LGPD (consentimentos, direitos do titular, pacote/anonimização com exceção do art. 16, ROPA,
// retenção em dry-run, incidentes com prazo de 3 dias úteis, DPO, dados sensíveis, mascaramento e logs).
// Uso:  DATABASE_URL=postgresql://postgres:pg@127.0.0.1:5432/lgpd npx tsx scripts/e2e/lgpd.ts
// Requer Postgres com o schema aplicado (prisma db push). Não usa internet nem chaves externas.
import { setup, check, summary, prisma, fails, Actor } from './qa5-lib'
import { addDiasUteis, estadoPrazo, feriadosNacionais, maiorDeIdade, protocoloValido } from '../../src/modules/lgpd/prazos'
import { hashDocumento, mascararCpf, mascararEmail, mascararTelefone, redigirLog, redigirTexto, sanitizarUrl, conferirSegredo, hashSegredo } from '../../src/modules/lgpd/mascara'
import { validarCatalogo, CATALOGO } from '../../src/modules/lgpd/catalogo'
import { jobRetencao } from '../../src/modules/lgpd/retencao'
import { jobIncidentes } from '../../src/modules/lgpd/incidentes'
import { totalSeeds } from '../../src/modules/lgpd/ropa'
import { VERSAO_MODELO } from '../../src/modules/lgpd/textos'

const secao = (t: string) => console.log(`\n== ${t}`)
const CPF_OK = '529.982.247-25'
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms))

async function main() {
  // ---------------------------------------------------------------- unidades puras
  secao('Funções puras: máscara, redação, prazos, catálogo')
  check('mascara CPF', mascararCpf(CPF_OK) === '***.982.247-**', mascararCpf(CPF_OK))
  check('mascara CPF só dígitos', mascararCpf('52998224725') === '***.982.247-**')
  check('mascara e-mail', mascararEmail('maria@exemplo.com') === 'm***@exemplo.com')
  check('mascara telefone', mascararTelefone('(11) 99999-1234') === '(**) *****-1234')
  const jwt = 'eyJhbGciOiJIUzI1NiJ9.eyJpZCI6IjEyMyJ9.assinaturaAbc123'
  check('redigirTexto remove JWT', !redigirTexto(`token ${jwt} fim`).includes('eyJ'))
  check('redigirTexto remove Bearer', !redigirTexto('Authorization: Bearer abcdef1234567890xyz').includes('abcdef1234567890xyz'))
  check('redigirTexto mascara CPF formatado', !redigirTexto(`cpf ${CPF_OK}`).includes('529.982'))
  check('redigirTexto remove senha=', !redigirTexto('login senha=Segredo!123&x=1').includes('Segredo!123'))
  const red: any = redigirLog({ senha: 'abc', token: 't', cpf: CPF_OK, nested: { password: 'p', apiKey: 'k', documento: '52998224725', obs: `CPF ${CPF_OK}` }, ok: 1 })
  check('redigirLog omite segredos', red.senha === '[omitido]' && red.token === '[omitido]' && red.nested.password === '[omitido]' && red.nested.apiKey === '[omitido]', red)
  check('redigirLog mascara CPF em chaves e textos', red.cpf === '***.982.247-**' && red.nested.documento === '***.982.247-**' && !String(red.nested.obs).includes('529.982'), red)
  const su = sanitizarUrl(`/api/x/${'52998224725'}/y?token=ABC&cpf=${CPF_OK}&page=2&senha=zzz`)
  check('sanitizarUrl', !su.includes('ABC') && !su.includes('52998224725') && !su.includes('zzz') && su.includes('page=2'), su)
  const { hash, salt } = hashSegredo('ABCD-2345')
  check('segredo de acompanhamento confere', conferirSegredo('abcd2345', hash, salt) && !conferirSegredo('ABCD-2346', hash, salt))
  check('hashDocumento estável e por tenant', hashDocumento(CPF_OK, 'a') === hashDocumento('52998224725', 'a') && hashDocumento(CPF_OK, 'a') !== hashDocumento(CPF_OK, 'b'))
  // 3 dias úteis: sexta 2026-10-09 12:00 -> quarta 2026-10-14 (12 de outubro, segunda, é feriado)
  const sex = new Date('2026-10-09T12:00:00Z')
  check('3 dias úteis pula fim de semana e feriado nacional', addDiasUteis(sex, 3).toISOString().slice(0, 10) === '2026-10-15', addDiasUteis(sex, 3).toISOString())
  check('3 dias úteis simples', addDiasUteis(new Date('2026-10-05T12:00:00Z'), 3).toISOString().slice(0, 10) === '2026-10-08')
  check('feriados incluem Sexta-feira Santa 2026', feriadosNacionais(2026).has('2026-04-03'))
  const t0 = new Date('2026-10-01T00:00:00Z')
  check('prazo: no prazo / vencendo / vencida', estadoPrazo(t0, new Date('2026-10-16T00:00:00Z'), true, new Date('2026-10-03T00:00:00Z')).estado === 'NO_PRAZO' && estadoPrazo(t0, new Date('2026-10-16T00:00:00Z'), true, new Date('2026-10-13T00:00:00Z')).estado === 'VENCENDO' && estadoPrazo(t0, new Date('2026-10-16T00:00:00Z'), true, new Date('2026-10-17T00:00:00Z')).estado === 'VENCIDA')
  check('maioridade', maiorDeIdade('2000-01-01') === true && maiorDeIdade(new Date(Date.now() - 10 * 365 * 86400000)) === false && maiorDeIdade(null) === null)
  check('protocolo válido', protocoloValido('LGPD-2026-00001') && !protocoloValido('X-1'))
  const errosCat = validarCatalogo()
  check('catálogo coerente com o schema do Prisma', errosCat.length === 0, errosCat)

  // ---------------------------------------------------------------- ambiente
  const { call, t1, t2, server, base, close } = await setup()
  const T = t1.tenantId
  await prisma.eduInstitution.create({ data: { tenantId: T, nome: 'Instituto LGPD', sigla: 'ILGPD', email: 'contato@ilgpd.edu.br' } })
  await prisma.eduInstitution.create({ data: { tenantId: t2.tenantId, nome: 'Outro Instituto' } })
  const admin = await t1.mk('ADMIN')
  const admin2 = await t2.mk('ADMIN')
  const aluno: Actor = await t1.mk('STUDENT', true)
  const aluno2: Actor = await t1.mk('STUDENT', true)         // sem registros acadêmicos: será anonimizado por inteiro
  const menor: Actor = await t1.mk('STUDENT', true)
  const menor2: Actor = await t1.mk('STUDENT', true)        // menor sem responsável cadastrado
  const coord1 = await t1.mk('COORDINATOR')
  const coord2 = await t1.mk('COORDINATOR')
  const pub = (p: string) => `/public/edu/lgpd/${T}${p}`
  const L = (p: string) => `/edu/lgpd${p}`

  const nasc = new Date(); nasc.setFullYear(nasc.getFullYear() - 25)
  const nascMenor = new Date(); nascMenor.setFullYear(nascMenor.getFullYear() - 15)
  await prisma.student.update({ where: { id: aluno.studentId! }, data: { cpf: CPF_OK, dataNascimento: nasc, nomeCompleto: 'Maria Teste da Silva' } })
  await prisma.student.update({ where: { id: menor.studentId! }, data: { dataNascimento: nascMenor } })
  await prisma.student.update({ where: { id: menor2.studentId! }, data: { dataNascimento: nascMenor } })
  const userAluno = await prisma.user.findUniqueOrThrow({ where: { id: aluno.id } })
  const emailAluno = userAluno.email

  // dados acadêmicos (preservados) + dados anonimizáveis
  const prog = await prisma.academicProgram.create({ data: { tenantId: T, nome: 'Odontologia LGPD', modalidade: 'PRESENCIAL', cargaHorariaTotal: 4000 } })
  const term = await prisma.academicTerm.create({ data: { tenantId: T, codigo: '2026/2-lgpd', dataInicio: new Date('2026-08-03'), dataFim: new Date('2026-12-18') } })
  const enr = await prisma.enrollment.create({ data: { studentId: aluno.studentId!, programId: prog.id, termId: term.id } })
  const rec = await prisma.accountReceivable.create({ data: { tenantId: T, studentId: aluno.studentId!, descricao: 'Mensalidade', valor: 500, dataVencimento: new Date() } })
  const contato = await prisma.comContato.create({ data: { tenantId: T, nome: 'Maria Teste da Silva', email: emailAluno, telefone: '11988887777', documento: '52998224725', studentId: aluno.studentId!, tipo: 'ALUNO' } })
  await prisma.eduNotification.create({ data: { tenantId: T, canal: 'EMAIL', studentId: aluno.studentId!, destino: emailAluno, assunto: 'Cobrança', mensagem: 'Sua parcela vence amanhã.' } })
  const atendRecente = await prisma.apoAtendimento.create({ data: { tenantId: T, studentId: aluno.studentId!, tipo: 'PSICOLOGICO', dataHora: new Date(), profissionalId: admin.id, motivo: 'Ansiedade em provas', relato: 'Relato sigiloso', encaminhamentos: 'Psicólogo externo' } })
  const old = new Date(); old.setMonth(old.getMonth() - 80)
  const atendAntigo = await prisma.apoAtendimento.create({ data: { tenantId: T, studentId: aluno.studentId!, tipo: 'SOCIAL', dataHora: old, profissionalId: admin.id, motivo: 'Dificuldade financeira', relato: 'Relato antigo', createdAt: old } })
  const egresso = await prisma.apoEgresso.create({ data: { tenantId: T, studentId: aluno.studentId!, nome: 'Maria Teste da Silva', email: emailAluno, telefone: '11988887777', cpf: CPF_OK, linkedin: 'https://linkedin.com/in/maria', cargoAtual: 'Dentista' } })
  await prisma.apoEgressoTrajetoria.create({ data: { tenantId: T, egressoId: egresso.id, tipo: 'EMPREGO', organizacao: 'Clínica X', inicio: new Date() } })
  await prisma.apoRiscoSnapshot.create({ data: { tenantId: T, studentId: aluno.studentId!, score: 0.7, nivel: 'ALTO', fatores: {} } })
  await prisma.bibLeitor.create({ data: { tenantId: T, perfil: 'ALUNO', studentId: aluno.studentId!, nome: 'Maria Teste da Silva', documento: '52998224725', email: emailAluno } })

  // ---------------------------------------------------------------- 1) consentimentos
  secao('1) Consentimentos versionados + API pública')
  let r = await call(null, 'GET', pub('/textos'))
  const tMkt = r.json?.textos?.find((t: any) => t.finalidade === 'COMUNICACAO_MARKETING')
  check('textos públicos vigentes (modelo) com hash', r.status === 200 && tMkt?.versao === VERSAO_MODELO && tMkt?.textoHash?.length === 64 && r.json.cookiesNecessarios, r.text)
  r = await call(null, 'GET', `/public/edu/lgpd/inexistente-xyz/textos`)
  check('instituição inexistente => 404', r.status === 404)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'COMUNICACAO_MARKETING', versao: '9.9', nome: 'Fulano', email: 'fulano@x.com' })
  check('versão de texto desatualizada => 409 com texto vigente', r.status === 409, r.text)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'COMUNICACAO_MARKETING', versao: VERSAO_MODELO })
  check('consentimento sem identificação => 422', r.status === 422, r.text)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'COMUNICACAO_MARKETING', versao: VERSAO_MODELO, nome: 'Fulano', email: 'fulano@x.com', documento: '111.111.111-11' })
  check('CPF inválido => 400', r.status === 400)
  // contato prévio para testar sincronização com opt-in de comunicação
  const ck = await prisma.comContato.create({ data: { tenantId: T, nome: 'Fulano', email: 'fulano@x.com', tipo: 'OUTRO' } })
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'COMUNICACAO_MARKETING', versao: VERSAO_MODELO, nome: 'Fulano de Tal', email: 'Fulano@x.com', documento: CPF_OK }, { 'user-agent': 'TesteUA/1.0' })
  const consId = r.json?.id, recibo = r.json?.recibo
  check('consentimento concedido com recibo', r.status === 201 && consId && recibo, r.text)
  const row = await prisma.lgpConsentimento.findUnique({ where: { id: consId } })
  check('registro guarda versão, hash do texto, IP/UA só em hash, CPF só em hash', row?.versaoTexto === VERSAO_MODELO && row.textoHash === tMkt.textoHash && !!row.ipHash && !!row.uaHash && !String(row.ipHash).includes('127.0.0.1') && row.titularDocMascarado === '***.982.247-**' && row.titularDocHash === hashDocumento(CPF_OK, T) && row.status === 'ATIVO' && !row.reciboHash?.includes(recibo.replace(/-/g, '')), row)
  let pref = await prisma.comPreferencia.findFirst({ where: { tenantId: T, contatoId: ck.id, finalidade: 'MARKETING' } })
  check('consentimento de marketing reflete no opt-in da Comunicação', pref?.consentimento === true && pref.origem === 'LGPD_PORTAL', pref)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'COMUNICACAO_MARKETING', versao: VERSAO_MODELO, nome: 'Fulano de Tal', email: 'fulano@x.com' })
  check('repetir o mesmo consentimento é idempotente', r.status === 200 && r.json?.jaExistia === true && r.json.id === consId, r.text)
  r = await call(null, 'POST', pub('/consentimentos/revogar'), { id: consId, recibo: 'AAAA-BBBB-CCCC' })
  check('revogar com recibo inválido => 404', r.status === 404)
  r = await call(null, 'POST', pub('/consentimentos/revogar'), { id: consId, recibo })
  check('revogar com recibo válido', r.status === 200 && r.json?.revogados === 1, r.text)
  const rev = await prisma.lgpConsentimento.findUnique({ where: { id: consId } })
  pref = await prisma.comPreferencia.findFirst({ where: { tenantId: T, contatoId: ck.id, finalidade: 'MARKETING' } })
  check('revogação mantém a linha (prova) e faz opt-out na Comunicação', rev?.status === 'REVOGADO' && !!rev.revogadoEm && pref?.consentimento === false, { rev: rev?.status, pref: pref?.consentimento })

  // menores (art. 14)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'USO_IMAGEM', versao: VERSAO_MODELO, nome: 'Joãozinho', email: 'joaozinho@x.com', menor: true })
  check('menor sem responsável => 422 exigeResponsavel', r.status === 422 && r.json?.exigeResponsavel !== false, r.text)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'USO_IMAGEM', versao: VERSAO_MODELO, nome: 'Joãozinho', email: 'joaozinho@x.com', dataNascimento: nascMenor.toISOString().slice(0, 10) })
  check('menor detectado pela data de nascimento => 422', r.status === 422, r.text)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'USO_IMAGEM', versao: VERSAO_MODELO, nome: 'Joãozinho', email: 'joaozinho@x.com', menor: true, responsavel: { nome: 'Ana Responsável', parentesco: 'Mãe', email: 'ana@x.com', documento: CPF_OK, declaracao: true } })
  check('menor com responsável legal => 201 e vínculo ao responsável', r.status === 201, r.text)
  const cm = await prisma.lgpConsentimento.findUnique({ where: { id: r.json.id } })
  const resp = cm?.responsavelId ? await prisma.lgpResponsavel.findUnique({ where: { id: cm.responsavelId } }) : null
  check('responsável guardado sem CPF completo', cm?.menor === true && resp?.nome === 'Ana Responsável' && resp.docMascarado === '***.982.247-**' && !JSON.stringify(resp).includes(CPF_OK), resp)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'USO_IMAGEM', versao: VERSAO_MODELO, nome: 'Outro', email: 'outro@x.com', menor: true, responsavel: { nome: 'Ana', parentesco: 'Mãe', email: 'a@x.com', declaracao: false } })
  check('declaração do responsável é obrigatória', r.status === 400)

  // cookies: necessários vs opcionais, sem pré-marcação; consentimento anônimo por titularRef
  const ref = 'visitante-' + Math.random().toString(36).slice(2) + 'abcdef'
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'COOKIES_ANALITICOS', versao: VERSAO_MODELO, titularTipo: 'VISITANTE', titularRef: ref })
  check('cookie opcional consentido sem identificar o visitante', r.status === 201 && r.json?.finalidade === 'COOKIES_ANALITICOS', r.text)
  const ck1 = await prisma.lgpConsentimento.findFirst({ where: { tenantId: T, titularRef: ref } })
  check('cookie: canal COOKIE_BANNER, sem nome/e-mail', ck1?.canal === 'COOKIE_BANNER' && !ck1.titularEmail && !ck1.titularNome)
  r = await call(null, 'POST', pub('/consentimentos/revogar'), { titularRef: ref, finalidade: 'COOKIES_ANALITICOS' })
  check('cookie revogado pelo identificador do navegador', r.status === 200 && r.json?.revogados === 1, r.text)
  r = await call(null, 'POST', pub('/consentimentos/revogar'), { titularRef: 'curto' })
  check('titularRef curto é recusado', r.status === 400)

  // texto próprio da instituição (versionado e imutável)
  r = await call(admin, 'POST', L('/textos-consentimento'), { finalidade: 'COMUNICACAO_MARKETING', versao: '2.0', titulo: 'Divulgação', texto: 'Texto da instituição para receber divulgação por e-mail e WhatsApp, com revogação a qualquer momento.' })
  check('instituição publica nova versão do texto', r.status === 201, r.text)
  r = await call(admin, 'POST', L('/textos-consentimento'), { finalidade: 'COMUNICACAO_MARKETING', versao: '2.0', titulo: 'Divulgação', texto: 'Alterado depois de publicado, tentando reaproveitar a versão.' })
  check('versão publicada é imutável (409)', r.status === 409)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'COMUNICACAO_MARKETING', versao: VERSAO_MODELO, nome: 'Fulano', email: 'fulano@x.com' })
  check('versão antiga do texto não é mais aceita (409)', r.status === 409)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'COMUNICACAO_MARKETING', versao: '2.0', nome: 'Fulano', email: 'fulano@x.com' })
  check('consentimento na nova versão', r.status === 201 && r.json.versao === '2.0', r.text)
  r = await call(admin, 'GET', L('/consentimentos?finalidade=COMUNICACAO_MARKETING'))
  check('listagem mascara e-mail/nome/CPF', r.status === 200 && r.json.items.every((c: any) => !c.titularEmail || c.titularEmail.includes('***')) && !r.text.includes(CPF_OK) && !r.text.includes('fulano@x.com'), r.text.slice(0, 300))
  r = await call(admin, 'GET', L('/consentimentos/resumo'))
  check('resumo por finalidade', r.status === 200 && r.json.porFinalidade.COMUNICACAO_MARKETING, r.text)
  r = await call(aluno, 'GET', L('/consentimentos'))
  check('aluno não acessa a Central LGPD (403)', r.status === 403)
  r = await call(admin2, 'GET', L('/consentimentos'))
  check('isolamento por instituição na listagem', r.status === 200 && r.json.total === 0, r.text)

  // ---------------------------------------------------------------- 2) direitos do titular
  secao('2) Direitos do titular: protocolo, prazo, fila, pacote, anonimização')
  r = await call(null, 'POST', pub('/solicitacoes'), { tipo: 'ACESSO', nome: 'Maria Teste da Silva', email: emailAluno, documento: CPF_OK, descricao: 'Quero meus dados' })
  const protocolo = r.json?.protocolo, codigo = r.json?.codigoAcompanhamento
  check('solicitação pública gera protocolo e código', r.status === 201 && /^LGPD-\d{4}-\d{5}$/.test(protocolo) && codigo, r.text)
  const sol = await prisma.lgpSolicitacao.findFirstOrThrow({ where: { tenantId: T, protocolo } })
  const dias = Math.round((sol.prazoEm.getTime() - sol.createdAt.getTime()) / 86400000)
  check('prazo de 15 dias; CPF só em hash; senha em hash', dias === 15 && sol.docMascarado === '***.982.247-**' && !JSON.stringify(sol).includes(CPF_OK) && sol.senhaHash.length > 20 && sol.senhaHash !== codigo, { dias })
  const lembrete = await prisma.eduReminder.findFirst({ where: { tenantId: T, refType: 'LgpSolicitacao', refId: sol.id } })
  check('lembrete de prazo agendado para o DPO/administração', !!lembrete && lembrete.dueAt.getTime() === sol.prazoEm.getTime(), lembrete)
  r = await call(null, 'POST', pub('/solicitacoes/consulta'), { protocolo, codigo: 'ERRO-ERRO-ERRO' })
  check('consulta com código errado => 404 genérico', r.status === 404)
  r = await call(null, 'POST', pub('/solicitacoes/consulta'), { protocolo, codigo })
  check('consulta por protocolo + código', r.status === 200 && r.json.status === 'ABERTA' && r.json.prazoEstado === 'NO_PRAZO' && Array.isArray(r.json.andamentos) && r.json.andamentos.length >= 1 && !r.text.includes(emailAluno), r.text)
  r = await call(null, 'POST', pub('/solicitacoes'), { tipo: 'ACESSO', nome: 'X', email: 'x@x.com' })
  check('validação do formulário público (nome curto)', r.status === 400)
  r = await call(null, 'POST', pub('/solicitacoes'), { tipo: 'ACESSO', nome: 'Pessoa Qualquer', email: 'pq@x.com', documento: '123' })
  check('CPF inválido na solicitação => 400', r.status === 400)
  r = await call(admin, 'GET', L('/fila'))
  check('fila do DPO lista a solicitação com semáforo', r.status === 200 && r.json.items.some((i: any) => i.protocolo === protocolo && i.prazoEstado === 'NO_PRAZO') && r.json.resumo.semVerificacaoDeIdentidade >= 1 && !r.text.includes(emailAluno), r.text.slice(0, 400))
  r = await call(admin, 'GET', L(`/solicitacoes/${sol.id}`))
  check('detalhe sugere o cadastro do aluno (por e-mail) e traz trilha', r.status === 200 && r.json.sugestoes.some((s: any) => s.tipo === 'ALUNO' && s.id === aluno.studentId) && r.json.trilha.length >= 1, r.text.slice(0, 400))
  r = await call(admin2, 'GET', L(`/solicitacoes/${sol.id}`))
  check('outra instituição não vê a solicitação (404)', r.status === 404)
  r = await call(admin, 'GET', L(`/solicitacoes/${sol.id}/pacote`))
  check('pacote sem vínculo => 409', r.status === 409, r.text)
  r = await call(admin, 'POST', L(`/solicitacoes/${sol.id}/vincular`), { titularTipo: 'ALUNO', titularId: aluno.studentId })
  check('vincular ao aluno', r.status === 200)
  r = await call(admin, 'GET', L(`/solicitacoes/${sol.id}/pacote`))
  check('pacote sem verificar identidade => 409', r.status === 409, r.text)
  r = await call(admin, 'POST', L(`/solicitacoes/${sol.id}/verificar-identidade`), { metodo: 'DOCUMENTO_COM_FOTO' })
  check('identidade verificada', r.status === 200 && !!r.json.identidadeVerificadaEm)
  r = await call(admin, 'GET', L(`/solicitacoes/${sol.id}/pacote`))
  const pac = r.json
  const mods = (pac?.entidades ?? []).map((e: any) => e.model)
  check('pacote JSON varre as entidades do aluno', r.status === 200 && ['student', 'user', 'enrollment', 'accountReceivable', 'comContato', 'eduNotification', 'apoAtendimento', 'apoEgresso', 'apoEgressoTrajetoria', 'bibLeitor', 'apoRiscoSnapshot', 'lgpConsentimento'].filter((m) => m !== 'lgpConsentimento').every((m) => mods.includes(m)), mods)
  check('pacote não traz hash/senha/token', !/"(senhaHash|senhaSalt|password|reciboHash|uaHash|ipHash)"/.test(r.text) && !/senhaHash/.test(r.text), 'campos proibidos')
  check('pacote marca dados sensíveis e lista exceções do art. 16', pac.entidades.find((e: any) => e.model === 'apoAtendimento')?.sensivel === true && pac.excecoesArt16.length >= 2 && pac.hashConteudo?.length === 64 && pac.compartilhamento !== undefined, pac?.resumo)
  check('pacote de CPF aparece mascarado nos identificadores', pac.titular.identificadores.documentos[0] === '***.982.247-**')
  const sol2 = await prisma.lgpSolicitacao.findUniqueOrThrow({ where: { id: sol.id } })
  check('pacote registrado (data + hash) sem guardar o conteúdo', !!sol2.pacoteGeradoEm && sol2.pacoteHash === pac.hashConteudo)
  r = await call(admin, 'POST', L(`/solicitacoes/${sol.id}/responder`), { resultado: 'ATENDIDA', resposta: 'Enviamos o pacote com seus dados por canal seguro, conforme solicitado.' })
  check('responder (acesso) após gerar pacote', r.status === 200 && r.json.status === 'ATENDIDA', r.text)
  r = await call(null, 'POST', pub('/solicitacoes/consulta'), { protocolo, codigo })
  check('titular vê a resposta no portal', r.status === 200 && r.json.status === 'ATENDIDA' && /pacote/.test(r.json.resposta), r.text)
  const notif = await prisma.eduNotification.findFirst({ where: { tenantId: T, refType: 'LgpSolicitacao', refId: sol.id } })
  check('aviso ao titular não carrega dados pessoais no corpo', !!notif && !notif.mensagem.includes('Quero meus dados'))
  r = await call(admin, 'POST', L(`/solicitacoes/${sol.id}/responder`), { resultado: 'ATENDIDA', resposta: 'Segunda resposta que não deveria ser aceita.' })
  check('não responde duas vezes (409)', r.status === 409)
  const tr = await prisma.lgpTrilha.findMany({ where: { tenantId: T, refType: 'Solicitacao', refId: sol.id } })
  check('trilha de auditoria da solicitação', ['ABERTA', 'VINCULADA', 'IDENTIDADE_VERIFICADA', 'PACOTE_GERADO', 'RESPONDIDA'].every((a) => tr.some((t) => t.acao === a)), tr.map((t) => t.acao))

  // acesso direto pelo DPO: exige motivo
  r = await call(admin, 'GET', L(`/titulares/ALUNO/${aluno.studentId}/pacote`))
  check('exportação direta sem motivo => 400', r.status === 400)
  r = await call(admin, 'GET', L(`/titulares/ALUNO/${aluno.studentId}/pacote?motivo=${encodeURIComponent('Fiscalização da ANPD - ofício 123')}`))
  check('exportação direta com motivo', r.status === 200 && r.json?.formato === 'edumaster-lgpd-pacote/1')

  // ELIMINAÇÃO: dry-run, confirmação, exceção do art. 16
  r = await call(null, 'POST', pub('/solicitacoes'), { tipo: 'ELIMINACAO', nome: 'Maria Teste da Silva', email: emailAluno, documento: CPF_OK, descricao: 'Quero apagar meus dados' })
  const eli = await prisma.lgpSolicitacao.findFirstOrThrow({ where: { tenantId: T, protocolo: r.json.protocolo } })
  const eliCodigo = r.json.codigoAcompanhamento
  r = await call(admin, 'POST', L(`/solicitacoes/${eli.id}/executar`), {})
  check('executar sem vínculo => 409', r.status === 409)
  await call(admin, 'POST', L(`/solicitacoes/${eli.id}/vincular`), { titularTipo: 'ALUNO', titularId: aluno.studentId })
  r = await call(admin, 'POST', L(`/solicitacoes/${eli.id}/executar`), {})
  check('executar sem identidade => 409', r.status === 409)
  await call(admin, 'POST', L(`/solicitacoes/${eli.id}/verificar-identidade`), { metodo: 'PRESENCIAL' })
  r = await call(admin, 'POST', L(`/solicitacoes/${eli.id}/executar`), {})
  const plano = r.json?.plano
  const it = (m: string) => plano?.itens?.find((i: any) => i.model === m)
  check('dry-run por padrão: plano sem alterar nada', r.status === 200 && r.json.dryRun === true && !!plano, r.text.slice(0, 300))
  check('plano: histórico/financeiro MANTIDOS (art. 16), contatos anonimizados', it('enrollment')?.acaoPlanejada === 'MANTER' && it('accountReceivable')?.acaoPlanejada === 'MANTER' && it('comContato')?.acaoPlanejada === 'ANONIMIZAR' && it('apoEgressoTrajetoria')?.acaoPlanejada === 'ELIMINAR' && plano.aluno?.acao === 'MANTER' && /art\. 16/i.test(plano.excecaoArt16), plano?.itens?.map((i: any) => `${i.model}:${i.acaoPlanejada}`))
  check('plano: atendimento recente retido (guarda mínima), antigo anonimizável', it('apoAtendimento')?.registros === 2 && it('apoAtendimento')?.aplicaveis === 1 && it('apoAtendimento')?.retidos === 1, it('apoAtendimento'))
  check('dry-run não alterou nada', (await prisma.comContato.findUnique({ where: { id: contato.id } }))?.email === emailAluno && (await prisma.apoEgressoTrajetoria.count({ where: { egressoId: egresso.id } })) === 1)
  r = await call(admin, 'POST', L(`/solicitacoes/${eli.id}/executar`), { dryRun: false })
  check('execução real exige confirmar=true (400)', r.status === 400, r.text)
  r = await call(admin, 'POST', L(`/solicitacoes/${eli.id}/responder`), { resultado: 'ATENDIDA', resposta: 'Dados eliminados conforme solicitado, exceto os de guarda obrigatória.' })
  check('não é possível marcar como atendida sem executar (409)', r.status === 409, r.text)
  // consentimento ativo do aluno (para provar a revogação em cascata)
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'PESQUISA_EGRESSOS', versao: VERSAO_MODELO, nome: 'Maria Teste da Silva', email: emailAluno, titularTipo: 'ALUNO', titularId: aluno.studentId })
  const consAlunoId = r.json?.id
  r = await call(admin, 'POST', L(`/solicitacoes/${eli.id}/executar`), { dryRun: false, confirmar: true })
  check('execução real', r.status === 200 && r.json.dryRun === false && r.json.resultado.consentimentosRevogados >= 1, r.text.slice(0, 400))
  check('histórico escolar e financeiro preservados', (await prisma.enrollment.count({ where: { id: enr.id } })) === 1 && (await prisma.accountReceivable.count({ where: { id: rec.id } })) === 1)
  const stDepois = await prisma.student.findUniqueOrThrow({ where: { id: aluno.studentId! } })
  check('cadastro do aluno com matrícula é mantido (art. 16)', stDepois.nomeCompleto === 'Maria Teste da Silva' && stDepois.cpf === CPF_OK)
  const cDepois = await prisma.comContato.findUniqueOrThrow({ where: { id: contato.id } })
  check('contato anonimizado', cDepois.nome === 'Titular anonimizado' && !cDepois.email && !cDepois.telefone && !cDepois.documento && cDepois.ativo === false, cDepois)
  check('mensagens anonimizadas', (await prisma.eduNotification.count({ where: { tenantId: T, studentId: aluno.studentId!, mensagem: { contains: 'parcela' } } })) === 0)
  const aA = await prisma.apoAtendimento.findUniqueOrThrow({ where: { id: atendAntigo.id } })
  const aR = await prisma.apoAtendimento.findUniqueOrThrow({ where: { id: atendRecente.id } })
  check('atendimento sensível antigo anonimizado; recente retido pela guarda mínima', aA.relato === null && aA.motivo === null && aR.relato === 'Relato sigiloso')
  const eg = await prisma.apoEgresso.findUniqueOrThrow({ where: { id: egresso.id } })
  check('egresso anonimizado e trajetória eliminada', eg.nome === 'Titular anonimizado' && !eg.email && !eg.cpf && !eg.linkedin && (await prisma.apoEgressoTrajetoria.count({ where: { egressoId: egresso.id } })) === 0 && (await prisma.apoRiscoSnapshot.count({ where: { studentId: aluno.studentId! } })) === 0)
  const leitor = await prisma.bibLeitor.findFirstOrThrow({ where: { tenantId: T, studentId: aluno.studentId! } })
  check('leitor da biblioteca anonimizado', leitor.nome === 'Titular anonimizado' && !leitor.documento && !leitor.email)
  const uDepois = await prisma.user.findUniqueOrThrow({ where: { id: aluno.id } })
  check('conta de acesso anonimizada e desativada', uDepois.isActive === false && uDepois.email.endsWith('@anonimizado.invalid') && uDepois.firstName === 'Titular' && !uDepois.password.startsWith('$2'))
  const consDepois = await prisma.lgpConsentimento.findMany({ where: { tenantId: T, id: consAlunoId } })
  check('consentimentos do aluno revogados e sem identificação (prova mantida)', consDepois.length >= 1 && consDepois.every((c) => c.status === 'REVOGADO' && c.titularEmail === null && c.titularNome === 'Titular anonimizado'), consDepois)
  const solMesma = await prisma.lgpSolicitacao.findUniqueOrThrow({ where: { id: eli.id } })
  const solAntiga = await prisma.lgpSolicitacao.findUniqueOrThrow({ where: { id: sol.id } })
  check('solicitação em curso mantém contato para a resposta; as anteriores perdem a identificação', solMesma.email === emailAluno && solAntiga.nome === 'Titular anonimizado' && solAntiga.email === '')
  r = await call(admin, 'POST', L(`/solicitacoes/${eli.id}/responder`), { resultado: 'ATENDIDA_PARCIALMENTE', resposta: 'Eliminamos parte dos dados; o histórico escolar e os registros fiscais foram mantidos.' })
  check('atendimento parcial exige justificativa (422)', r.status === 422)
  r = await call(admin, 'POST', L(`/solicitacoes/${eli.id}/responder`), { resultado: 'ATENDIDA_PARCIALMENTE', resposta: 'Eliminamos parte dos dados; o histórico escolar e os registros fiscais foram mantidos.', justificativa: 'LGPD art. 16, I: guarda obrigatória do histórico escolar (LDB) e dos registros fiscais (CTN).' })
  check('resposta parcial com fundamento do art. 16', r.status === 200 && r.json.status === 'ATENDIDA_PARCIALMENTE', r.text)
  r = await call(null, 'POST', pub('/solicitacoes/consulta'), { protocolo: eli.protocolo, codigo: eliCodigo })
  check('portal mostra justificativa da exceção', r.status === 200 && /art\. 16/.test(r.json.justificativa), r.text)

  // aluno sem registro acadêmico: cadastro também é anonimizado
  const sol3 = await prisma.lgpSolicitacao.create({ data: { tenantId: T, protocolo: 'LGPD-2026-90001', tipo: 'ANONIMIZACAO', nome: 'Aluno Dois', email: 'a2@x.com', prazoEm: new Date(Date.now() + 15 * 86400000), senhaHash: 'x', senhaSalt: 'y', titularTipo: 'ALUNO', titularId: aluno2.studentId, identidadeVerificadaEm: new Date(), status: 'EM_ANALISE' } })
  r = await call(admin, 'POST', L(`/solicitacoes/${sol3.id}/executar`), { dryRun: false, confirmar: true })
  const st2 = await prisma.student.findUniqueOrThrow({ where: { id: aluno2.studentId! } })
  check('aluno sem matrícula/notas/cobranças: cadastro anonimizado (RA mantido)', r.status === 200 && st2.nomeCompleto === 'Titular anonimizado' && st2.cpf === null && !!st2.ra, r.text.slice(0, 300))

  // correção
  r = await call(null, 'POST', pub('/solicitacoes'), { tipo: 'CORRECAO', nome: 'Aluno Menor', email: 'menor@x.com', descricao: 'Meu nome está errado' })
  const cor = await prisma.lgpSolicitacao.findFirstOrThrow({ where: { tenantId: T, protocolo: r.json.protocolo } })
  await call(admin, 'POST', L(`/solicitacoes/${cor.id}/vincular`), { titularTipo: 'ALUNO', titularId: menor.studentId })
  await call(admin, 'POST', L(`/solicitacoes/${cor.id}/verificar-identidade`), { metodo: 'DOCUMENTO_COM_FOTO' })
  r = await call(admin, 'POST', L(`/solicitacoes/${cor.id}/corrigir`), { alteracoes: [{ entidade: 'student', registroId: aluno.studentId, campo: 'nomeCompleto', valor: 'Alheio' }] })
  check('corrigir registro de outro titular => 403', r.status === 403)
  r = await call(admin, 'POST', L(`/solicitacoes/${cor.id}/corrigir`), { alteracoes: [{ entidade: 'student', registroId: menor.studentId, campo: 'ra', valor: 'X' }] })
  check('campo fora da lista de correção => 400', r.status === 400)
  r = await call(admin, 'POST', L(`/solicitacoes/${cor.id}/corrigir`), { alteracoes: [{ entidade: 'student', registroId: menor.studentId, campo: 'nomeCompleto', valor: 'Nome Corrigido da Silva' }] })
  const stm = await prisma.student.findUniqueOrThrow({ where: { id: menor.studentId! } })
  check('correção aplicada, trilha mascarada', r.status === 200 && stm.nomeCompleto === 'Nome Corrigido da Silva' && !JSON.stringify(r.json).includes('Corrigido da Silva') && r.json.aplicadas[0].depois.startsWith('Nome C.'), r.text)

  // prazo + prorrogação + alerta
  const solV = await prisma.lgpSolicitacao.create({ data: { tenantId: T, protocolo: 'LGPD-2026-90002', tipo: 'CONFIRMACAO', nome: 'Atrasado Silva', email: 'atrasado@x.com', prazoEm: new Date(Date.now() - 86400000), createdAt: new Date(Date.now() - 16 * 86400000), senhaHash: 'x', senhaSalt: 'y' } })
  r = await call(admin, 'GET', L('/fila'))
  check('fila marca solicitação vencida', r.json.items.find((i: any) => i.id === solV.id)?.prazoEstado === 'VENCIDA' && r.json.resumo.vencidas >= 1)
  const { runEduJobs } = await import('../../src/modules/core/jobs')
  const jobs: any = await runEduJobs()
  check('job de prazos alerta vencidas', jobs['lgpd:prazos-solicitacoes']?.ok === true && jobs['lgpd:prazos-solicitacoes'].result.alertas >= 1, jobs['lgpd:prazos-solicitacoes'])
  const lemV = await prisma.eduReminder.findFirst({ where: { tenantId: T, refType: 'LgpSolicitacao', refId: solV.id } })
  check('alerta CRÍTICO criado para vencida', lemV?.severity === 'CRITICO', lemV)
  r = await call(admin, 'POST', L(`/solicitacoes/${solV.id}/prorrogar`), { motivo: 'curto' })
  check('prorrogar exige motivo', r.status === 400)
  r = await call(admin, 'POST', L(`/solicitacoes/${solV.id}/prorrogar`), { motivo: 'Complexidade do pedido e volume de registros a localizar.' })
  check('prorrogar uma vez', r.status === 200 && r.json.prazoEstado !== 'VENCIDA', r.text)
  r = await call(admin, 'POST', L(`/solicitacoes/${solV.id}/prorrogar`), { motivo: 'Segunda prorrogação não permitida pela regra.' })
  check('segunda prorrogação => 409', r.status === 409)
  r = await call(admin, 'POST', L(`/solicitacoes/${solV.id}/status`), { status: 'AGUARDANDO_TITULAR', mensagem: 'Envie uma cópia do documento de identidade.' })
  check('pedir informação ao titular', r.status === 200)
  const codV = 'ZZZZ-YYYY-XXXX-WWWW'
  const hs = hashSegredo(codV); await prisma.lgpSolicitacao.update({ where: { id: solV.id }, data: { senhaHash: hs.hash, senhaSalt: hs.salt } })
  r = await call(null, 'POST', pub('/solicitacoes/responder'), { protocolo: 'LGPD-2026-90002', codigo: codV, mensagem: 'Segue o documento solicitado, enviado ao DPO.' })
  check('titular responde ao pedido de esclarecimento', r.status === 200 && (await prisma.lgpSolicitacao.findUniqueOrThrow({ where: { id: solV.id } })).status === 'EM_ANALISE')
  // bloqueio por tentativas
  for (let i = 0; i < 5; i++) await call(null, 'POST', pub('/solicitacoes/consulta'), { protocolo: 'LGPD-2026-90002', codigo: 'ERRO-ERRO-ERRO-ERRO' })
  r = await call(null, 'POST', pub('/solicitacoes/consulta'), { protocolo: 'LGPD-2026-90002', codigo: codV })
  check('consulta bloqueada após 5 códigos errados (429)', r.status === 429, r.text)

  // revogação de consentimento via solicitação
  r = await call(null, 'POST', pub('/consentimentos'), { finalidade: 'COMPARTILHAMENTO_PARCEIROS', versao: VERSAO_MODELO, nome: 'Aluno Menor', email: 'menor@x.com', titularTipo: 'ALUNO', titularId: menor.studentId, menor: true, responsavel: { nome: 'Pai Responsável', parentesco: 'Pai', telefone: '11999990000', declaracao: true } })
  check('consentimento do menor vinculado ao aluno', r.status === 201, r.text)
  const solRev = await prisma.lgpSolicitacao.create({ data: { tenantId: T, protocolo: 'LGPD-2026-90003', tipo: 'REVOGACAO_CONSENTIMENTO', nome: 'Pai Responsável', email: 'pai@x.com', prazoEm: new Date(Date.now() + 15 * 86400000), senhaHash: 'x', senhaSalt: 'y', titularTipo: 'ALUNO', titularId: menor.studentId, identidadeVerificadaEm: new Date(), status: 'EM_ANALISE' } })
  r = await call(admin, 'POST', L(`/solicitacoes/${solRev.id}/executar`), {})
  check('revogação em dry-run mostra quantos consentimentos', r.status === 200 && r.json.dryRun === true && r.json.consentimentosAtivos >= 1, r.text)
  r = await call(admin, 'POST', L(`/solicitacoes/${solRev.id}/executar`), { dryRun: false, confirmar: true })
  check('revogação executada', r.status === 200 && r.json.consentimentosRevogados >= 1, r.text)

  // ---------------------------------------------------------------- 3) ROPA
  secao('3) ROPA / inventário de tratamento')
  r = await call(admin, 'GET', L('/ropa?pageSize=100'))
  check('ROPA pré-populado com as atividades do EduMaster', r.status === 200 && r.json.total >= totalSeeds && r.json.items.some((a: any) => a.codigo === 'APO-ATENDIMENTO' && a.dadosSensiveis && a.baseLegal === 'TUTELA_SAUDE') && r.json.items.every((a: any) => a.finalidade && a.baseLegal), r.json?.total)
  r = await call(admin, 'POST', L('/ropa/seed'), {})
  check('seed idempotente', r.status === 200 && r.json.criadas === 0 && r.json.existentes >= totalSeeds, r.text)
  const novaAtiv = { codigo: 'teste-sens', atividade: 'Teste sensível', finalidade: 'Finalidade de teste do inventário', baseLegal: 'LEGITIMO_INTERESSE', dadosSensiveis: true }
  r = await call(admin, 'POST', L('/ropa'), novaAtiv)
  check('dado sensível com legítimo interesse é recusado (art. 11)', r.status === 422, r.text)
  r = await call(admin, 'POST', L('/ropa'), { ...novaAtiv, baseLegal: 'CONSENTIMENTO_DESTACADO', compartilhamento: [{ destinatario: 'Laboratório X', finalidade: 'Exame' }] })
  check('atividade manual criada', r.status === 201 && r.json.codigo === 'TESTE-SENS', r.text)
  const aid = r.json?.id
  r = await call(admin, 'PUT', L(`/ropa/${aid}`), { baseLegal: 'EXECUCAO_CONTRATO' })
  check('atualização também respeita a regra do dado sensível', r.status === 422, r.text)
  r = await call(admin, 'POST', L(`/ropa/${aid}/revisar`), {})
  check('revisão marca ATIVA', r.status === 200 && r.json.status === 'ATIVA' && !!r.json.revisadoEm)
  r = await call(admin, 'DELETE', L(`/ropa/${aid}`))
  check('exclusão só descontinua (histórico mantido)', r.status === 204 && (await prisma.lgpAtividadeTratamento.findUniqueOrThrow({ where: { id: aid } })).status === 'DESCONTINUADA')
  r = await call(admin, 'GET', L('/ropa?formato=csv'))
  check('exportação CSV do ROPA', r.status === 200 && r.text.includes('APO-ATENDIMENTO') && r.text.includes('"Código"'), r.text.slice(0, 200))
  r = await call(admin, 'GET', L('/ropa?sensiveis=true&menores=true'))
  check('filtros sensíveis/menores', r.status === 200 && r.json.items.every((a: any) => a.dadosSensiveis && a.dadosMenores) && r.json.items.length >= 1)

  // ---------------------------------------------------------------- 4) Retenção
  secao('4) Retenção, expurgo e dry-run')
  r = await call(admin, 'GET', L('/retencao/politicas'))
  check('políticas padrão criadas', r.status === 200 && r.json.items.length >= 8 && r.json.modoJob === 'DRY_RUN', r.text.slice(0, 200))
  const polMsg = r.json.items.find((p: any) => p.alvo === 'MENSAGENS_ENVIADAS')
  const polSeg = r.json.items.find((p: any) => p.alvo === 'EVENTOS_SEGURANCA')
  const polAt = r.json.items.find((p: any) => p.alvo === 'ATENDIMENTOS_APOIO')
  r = await call(admin, 'PUT', L(`/retencao/politicas/${polSeg.id}`), { prazoMeses: 2 })
  check('prazo abaixo do mínimo legal é recusado (Marco Civil)', r.status === 422, r.text)
  r = await call(admin, 'PUT', L(`/retencao/politicas/${polAt.id}`), { prazoMeses: 12 })
  check('atendimento sensível: mínimo de guarda 60 meses', r.status === 422)
  const velho = new Date(); velho.setMonth(velho.getMonth() - 30)
  const nOld = await prisma.eduNotification.create({ data: { tenantId: T, canal: 'EMAIL', destino: 'velho@x.com', assunto: 'Aviso antigo', mensagem: 'conteúdo antigo', createdAt: velho } })
  await prisma.segEvento.create({ data: { tenantId: T, tipo: 'login_falho', createdAt: velho } })
  const candOld = await prisma.admCandidato.create({ data: { tenantId: T, protocolo: 'RET-OLD-1', nome: 'Candidato Antigo', email: 'cand@x.com', cpf: CPF_OK, createdAt: velho } })
  await prisma.admInteracao.create({ data: { tenantId: T, candidatoId: candOld.id, descricao: 'Ligou' } })
  const logsAntes = await prisma.lgpRetencaoExecucao.count({ where: { tenantId: T } })
  r = await call(admin, 'POST', L('/retencao/executar'), {})
  check('execução manual é dry-run por padrão e conta o que seria afetado', r.status === 200 && r.json.dryRun === true && r.json.resultados.find((x: any) => x.alvo === 'MENSAGENS_ENVIADAS')?.afetados >= 1 && r.json.resultados.find((x: any) => x.alvo === 'CANDIDATOS_NAO_MATRICULADOS')?.afetados >= 1, r.text.slice(0, 400))
  check('dry-run não alterou nada', (await prisma.eduNotification.findUniqueOrThrow({ where: { id: nOld.id } })).mensagem === 'conteúdo antigo' && (await prisma.admCandidato.findUniqueOrThrow({ where: { id: candOld.id } })).nome === 'Candidato Antigo')
  check('execuções registradas sem dados pessoais', (await prisma.lgpRetencaoExecucao.count({ where: { tenantId: T } })) > logsAntes && !JSON.stringify(await prisma.lgpRetencaoExecucao.findMany({ where: { tenantId: T } })).includes('cand@x.com'))
  r = await call(admin, 'POST', L('/retencao/executar'), { dryRun: false })
  check('expurgo real exige confirmação', r.status === 400)
  process.env.LGPD_RETENCAO_EXECUTAR = ''
  let j: any = await jobRetencao()
  check('job agendado roda em dry-run por padrão', j.modo === 'DRY_RUN' && (await prisma.eduNotification.findUniqueOrThrow({ where: { id: nOld.id } })).mensagem === 'conteúdo antigo', j)
  process.env.LGPD_RETENCAO_EXECUTAR = 'true'
  j = await jobRetencao()
  process.env.LGPD_RETENCAO_EXECUTAR = ''
  check('com a flag LGPD_RETENCAO_EXECUTAR=true o job executa', j.modo === 'EXECUCAO' && (await prisma.eduNotification.findUniqueOrThrow({ where: { id: nOld.id } })).mensagem === '[conteúdo removido - LGPD]', j)
  const cA = await prisma.admCandidato.findUniqueOrThrow({ where: { id: candOld.id } })
  check('candidato não matriculado anonimizado e interações removidas', cA.nome === 'Titular anonimizado' && !cA.cpf && !cA.email && (await prisma.admInteracao.count({ where: { candidatoId: candOld.id } })) === 0)
  check('eventos de segurança antigos eliminados', (await prisma.segEvento.count({ where: { tenantId: T, tipo: 'login_falho', createdAt: { lt: new Date(Date.now() - 365 * 86400000) } } })) === 0)
  check('retenção nunca toca matrícula/financeiro/histórico', (await prisma.enrollment.count({ where: { id: enr.id } })) === 1 && (await prisma.accountReceivable.count({ where: { id: rec.id } })) === 1)
  r = await call(admin, 'GET', L('/retencao/execucoes?dryRun=false'))
  check('histórico de execuções reais', r.status === 200 && r.json.items.some((e: any) => e.dryRun === false && e.afetados >= 1 && e.origem === 'JOB'))
  r = await call(admin, 'GET', L('/retencao/alvos'))
  check('alvos documentam o que é protegido (art. 16)', r.status === 200 && r.json.protegidosArt16.length >= 4 && polMsg)

  // ---------------------------------------------------------------- 5) Incidentes
  secao('5) Incidentes de segurança (art. 48)')
  r = await call(admin, 'POST', L('/incidentes'), { titulo: 'Planilha de alunos enviada por engano', descricao: 'Planilha com CPF e notas enviada a destinatário externo.', severidade: 'ALTA', ciencia: '2026-10-09T12:00:00Z', riscoRelevante: true, dadosSensiveis: false, titularesAfetados: 120, categoriasDados: ['Nome', 'CPF', 'Notas'] })
  const inc = r.json
  check('incidente criado com prazo de 3 dias úteis (sexta -> quinta, pulando feriado 12/10)', r.status === 201 && String(inc.prazoComunicacaoEm).startsWith('2026-10-15') && /^INC-\d{4}-\d{3}$/.test(inc.numero) && inc.checklist.length >= 10 && inc.comunicacaoObrigatoria === true, r.text.slice(0, 300))
  check('alerta crítico agendado', (await prisma.eduReminder.findFirst({ where: { tenantId: T, refType: 'LgpIncidente', refId: inc.id } }))?.severity === 'CRITICO')
  r = await call(admin, 'GET', L(`/incidentes/${inc.id}`))
  check('linha do tempo com a detecção', r.status === 200 && r.json.eventos.some((e: any) => e.tipo === 'DETECCAO') && r.json.prazoEstado === 'VENCIDA', { estado: r.json?.prazoEstado })
  r = await call(admin, 'POST', L(`/incidentes/${inc.id}/encerrar`), { causa: 'Erro humano no envio.', medidasCorretivas: 'Treinamento e DLP.' })
  check('encerrar com checklist pendente => 422 com pendências', r.status === 422 && Array.isArray(r.json?.pendencias) || r.status === 422, r.text.slice(0, 200))
  r = await call(admin, 'POST', L(`/incidentes/${inc.id}/eventos`), { tipo: 'CONTENCAO', descricao: 'Destinatário confirmou exclusão da planilha.' })
  check('evento de contenção', r.status === 201)
  for (const c of inc.checklist.filter((x: any) => x.obrigatorio)) await call(admin, 'POST', L(`/incidentes/${inc.id}/checklist/${c.codigo}`), { feito: true })
  r = await call(admin, 'POST', L(`/incidentes/${inc.id}/encerrar`), { causa: 'Erro humano no envio.', medidasCorretivas: 'Treinamento e DLP.' })
  check('risco relevante sem comunicação não encerra (422)', r.status === 422, r.text)
  jobs.incidentes = await jobIncidentes()
  check('job alerta incidente com comunicação pendente/vencida', jobs.incidentes.alertas >= 1, jobs.incidentes)
  r = await call(admin, 'POST', L(`/incidentes/${inc.id}/comunicar-anpd`), { protocolo: 'ANPD-2026-0001', em: '2026-10-14T10:00:00Z' })
  check('comunicação à ANPD registrada', r.status === 200 && r.json.anpdProtocolo === 'ANPD-2026-0001' && r.json.pendenciaAnpd === false)
  r = await call(admin, 'POST', L(`/incidentes/${inc.id}/comunicar-titulares`), { meio: 'E-mail individual aos 120 titulares', titularesNotificados: 120, em: '2026-10-16T10:00:00Z' })
  const ev = await prisma.lgpIncidenteEvento.findMany({ where: { incidenteId: inc.id } })
  check('comunicação aos titulares fora do prazo é sinalizada na linha do tempo', r.status === 200 && ev.some((e) => e.tipo === 'COMUNICACAO_TITULARES' && /FORA do prazo/.test(e.descricao)))
  r = await call(admin, 'POST', L(`/incidentes/${inc.id}/encerrar`), { causa: 'Erro humano no envio da planilha.', medidasCorretivas: 'Treinamento, DLP e revisão de permissões.' })
  check('incidente encerrado após comunicações', r.status === 200 && r.json.status === 'ENCERRADO' && r.json.prazoEstado === 'ENCERRADA', r.text.slice(0, 200))
  r = await call(admin, 'POST', L('/incidentes'), { titulo: 'Tentativa de acesso bloqueada', descricao: 'Acesso indevido bloqueado pela barreira, sem exposição.', severidade: 'BAIXA' })
  const inc2 = r.json
  for (const c of inc2.checklist.filter((x: any) => x.obrigatorio)) await call(admin, 'POST', L(`/incidentes/${inc2.id}/checklist/${c.codigo}`), { feito: true })
  r = await call(admin, 'POST', L(`/incidentes/${inc2.id}/encerrar`), { causa: 'Tentativa externa bloqueada.', medidasCorretivas: 'Regra de firewall reforçada.' })
  check('sem risco relevante exige justificativa de não comunicação (422)', r.status === 422)
  r = await call(admin, 'POST', L(`/incidentes/${inc2.id}/encerrar`), { causa: 'Tentativa externa bloqueada.', medidasCorretivas: 'Regra de firewall reforçada.', justificativaSemComunicacao: 'Nenhum dado foi acessado; não há risco ou dano relevante aos titulares.' })
  check('encerra com justificativa', r.status === 200)

  // ---------------------------------------------------------------- 6) DPO
  secao('6) Encarregado (DPO) e página pública')
  r = await call(null, 'GET', pub('/dpo'))
  check('página pública sem DPO orienta o titular', r.status === 200 && r.json.encarregado === null && r.json.aviso && r.json.prazoRespostaDias === 15 && r.json.instituicao.nome === 'Instituto LGPD', r.text)
  r = await call(coord1, 'GET', L('/fila'))
  check('coordenador comum não acessa a fila (403)', r.status === 403)
  r = await call(admin, 'POST', L('/dpo'), { nome: 'Dra. Camila Encarregada', email: 'dpo@ilgpd.edu.br', telefone: '11 4000-0000', cargo: 'Encarregada de Dados', horarioAtendimento: 'Seg a Sex, 9h às 17h', userId: coord1.id })
  check('DPO designado (vinculado a usuário)', r.status === 201, r.text)
  r = await call(null, 'GET', pub('/dpo'))
  check('página pública divulga o encarregado e o canal', r.status === 200 && r.json.encarregado?.email === 'dpo@ilgpd.edu.br' && r.json.encarregado.nome.includes('Camila'), r.text)
  r = await call(coord1, 'GET', L('/fila'))
  check('usuário designado como DPO acessa a Central LGPD', r.status === 200)
  r = await call(coord2, 'GET', L('/fila'))
  check('outro coordenador continua sem acesso', r.status === 403)
  r = await call(coord1, 'GET', L('/acesso'))
  check('endpoint de acesso informa gestor', r.json?.gestor === true)
  r = await call(admin, 'POST', L('/dpo'), { nome: 'Novo Encarregado Silva', email: 'novo@ilgpd.edu.br' })
  const ativos = await prisma.lgpDpo.count({ where: { tenantId: T, ativo: true } })
  check('apenas um encarregado ativo por instituição', r.status === 201 && ativos === 1)
  r = await call(coord1, 'GET', L('/fila'))
  check('DPO substituído perde o acesso', r.status === 403)
  r = await call(null, 'GET', pub('/politica'))
  check('dados públicos da Política de Privacidade (ROPA resumido, sem segurança)', r.status === 200 && r.json.atividades.length >= totalSeeds && !r.text.includes('medidasSeguranca') && r.json.encarregado, r.text.slice(0, 200))

  // ---------------------------------------------------------------- 7) dados sensíveis e menores
  secao('7) Dados sensíveis, menores e log de acesso')
  r = await call(admin, 'GET', `/edu/apoio/atendimentos/${atendRecente.id}`)
  await sleep(400)
  const acessos = await prisma.lgpAcessoSensivel.findMany({ where: { tenantId: T, recurso: 'apoio/atendimentos' } })
  check('leitura de atendimento registra quem viu o quê', acessos.some((a) => a.userId === admin.id && a.recursoId === atendRecente.id && a.categoria === 'SAUDE' && a.titularId === aluno.studentId && a.acao === 'LEITURA'), acessos)
  r = await call(admin, 'GET', L(`/acessos-sensiveis?userId=${admin.id}`))
  check('consulta de acessos traz o nome do usuário', r.status === 200 && r.json.items.length >= 1 && r.json.items[0].usuario, r.text.slice(0, 200))
  r = await call(admin, 'GET', L('/campos-sensiveis'))
  check('catálogo de campos sensíveis', r.status === 200 && r.json.campos.some((c: any) => c.modelo === 'apoAtendimento' && c.campo === 'relato' && c.categoria === 'SAUDE'))
  r = await call(admin, 'POST', L('/campos-sensiveis'), { modelo: 'student', campo: 'foto', categoria: 'BIOMETRIA' })
  check('instituição marca campo sensível adicional', r.status === 201)
  r = await call(admin, 'GET', L('/menores/pendencias'))
  check('menores sem responsável legal listados', r.status === 200 && r.json.items.some((m: any) => m.id === menor2.studentId) && !r.json.items.some((m: any) => m.id === menor.studentId), r.text.slice(0, 200))
  const antes = await prisma.lgpAcessoSensivel.count({ where: { tenantId: T } })
  await call(admin, 'GET', `/edu/apoio/atendimentos/meus`)
  await sleep(200)
  check('leitura do próprio atendimento (aluno) não gera log de terceiros', (await prisma.lgpAcessoSensivel.count({ where: { tenantId: T } })) === antes)

  // ---------------------------------------------------------------- 8) logs
  secao('8) Logs sem senha/token/CPF')
  const capturado: string[] = []
  const so = process.stdout.write.bind(process.stdout), se = process.stderr.write.bind(process.stderr)
  ;(process.stdout as any).write = (c: any, ...a: any[]) => { capturado.push(String(c)); return so(c, ...a) }
  ;(process.stderr as any).write = (c: any, ...a: any[]) => { capturado.push(String(c)); return se(c, ...a) }
  await call(admin, 'GET', `/edu/lgpd/acesso?token=SEGREDO-TOKEN-123&cpf=${CPF_OK}&senha=MinhaSenha9`)
  await call(admin, 'GET', `/edu/lgpd/titulares/buscar?q=${encodeURIComponent(CPF_OK)}`)
  console.error('falha ao processar', { password: 'SenhaSuperSecreta', cpf: CPF_OK, nota: `CPF do aluno ${CPF_OK}`, headers: { authorization: 'Bearer abcdefghijklmnop123456' } }, new Error(`erro com token=ABC123XYZ456 e cpf ${CPF_OK}`))
  console.log(`Bearer ${jwt} / password=outraSenha1`)
  await sleep(100)
  ;(process.stdout as any).write = so
  ;(process.stderr as any).write = se
  const saida = capturado.join('')
  check('log HTTP não traz token/senha/CPF da query', !/SEGREDO-TOKEN-123|MinhaSenha9|529\.982\.247-25|52998224725/.test(saida), saida.slice(0, 300))
  check('console.* redige senha, Bearer, JWT e CPF', !/SenhaSuperSecreta|abcdefghijklmnop123456|ABC123XYZ456|outraSenha1|eyJhbGci/.test(saida) && !saida.includes('529.982.247-25'))
  const ev1 = await prisma.eduAuditEvent.findMany({ where: { tenantId: T }, take: 5 })
  check('auditoria do EduMaster passa por redação', ev1.length >= 0)
  // audit com segredos
  const { audit } = await import('../../src/modules/core/notify')
  await audit({ tenantId: T, modulo: 'teste', acao: 'X', detalhes: { token: 'tok-secreto-1', cpf: CPF_OK, senha: 'abc' } })
  const aud = await prisma.eduAuditEvent.findFirstOrThrow({ where: { tenantId: T, modulo: 'teste' } })
  check('audit() grava detalhes redigidos', JSON.stringify(aud.detalhes) .includes('[omitido]') && !JSON.stringify(aud.detalhes).includes('tok-secreto-1') && !JSON.stringify(aud.detalhes).includes(CPF_OK), aud.detalhes)

  summary()
  server.close()
  await prisma.$disconnect()
  process.exit(fails.length ? 1 : 0)
}
main().catch((e) => { console.error(e); process.exit(2) })
